const source = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const diagnostics = (source.diagnostics && typeof source.diagnostics === 'object') ? source.diagnostics : {};
const account = (source.account && typeof source.account === 'object') ? source.account : {};
const legacyErrors = {
  DIVISION_CHANGE_NOT_CONFIRMED: ['WFX chưa xác nhận đổi Division', 'Kiểm tra menu Division trên WFX rồi thử lại.'],
  MODULE_FAILED: ['Không thể thao tác module WFX', 'Mở Log kỹ thuật để xem lỗi gốc cuối cùng.'],
  MODULE_SEARCH_NOT_READY: ['Ô tìm kiếm của module chưa sẵn sàng', 'Bấm List, chờ danh sách tải xong rồi thử tìm lại.']
};
const redact = value => String(value || '')
  .replace(/https?:\/\/[^\s<>'\"]+/gi, '[URL đã ẩn]')
  .replace(/\b(password|passwd|pwd|cookie|session[_\s-]?id|login[_\s-]?id|query|article[_\s-]?code|buyer[_\s-]?reference|style[_\s-]?code)\b\s*[:=]\s*(\"[^\"]*\"|'[^']*'|[^\s,;]+)/gi, '$1=[đã ẩn]')
  .replace(/\bcode\s+(chính\s+xác|cần\s+tìm)\s*:\s*[^\s,;]+/gi, 'Code [đã ẩn]');
const eventType = String(source.event_type || 'unknown');
const eventLabel = eventType === 'user_feedback'
  ? (source.kind === 'bug' ? 'Báo lỗi từ người dùng' : 'Góp ý tính năng')
  : eventType === 'automation_error' ? 'Lỗi automation' : 'Sự kiện khác';
const methodLabel = String(source.method_label || source.method || 'Tác vụ WFX');
const legacy = legacyErrors[source.code] || [];
const errorTitle = String(source.error_title || legacy[0] || `${methodLabel} chưa hoàn tất`);
const errorDetail = redact(source.error_detail || source.message || 'Automation không trả về mô tả chi tiết.');
const suggestion = String(source.suggestion || legacy[1] || 'Mở Log kỹ thuật và dùng Run ID để đối chiếu.');
const division = [account.division_label, account.division_name].filter(Boolean).join(' · ') || diagnostics.current_division || '';
const lines = [
  `📣 WFX SMART · ${eventLabel}`,
  `🕒 Thời gian: ${source.timestamp || new Date().toISOString()}`,
  account.user_id ? `👤 Tài khoản: ${account.user_id}` : '',
  account.company_id ? `🏢 Company: ${account.company_id}` : '',
  division ? `🏭 Division: ${division}` : '',
  source.app_version ? `📦 Phiên bản: ${source.app_version}` : ''
];
if (eventType === 'automation_error') {
  lines.push(
    `⚙️ Tác vụ: ${methodLabel}`,
    source.module ? `📂 Module: ${source.module}` : '',
    source.filter_kind ? `🔍 Trường tìm: ${source.filter_kind}` : '',
    `❌ Lỗi: ${errorTitle}`,
    `📝 Chi tiết: ${errorDetail}`,
    `💡 Xử lý: ${suggestion}`,
    source.code ? `🔧 Mã kỹ thuật: ${source.code}` : '',
    source.run_id ? `🔎 Run ID: ${source.run_id}` : ''
  );
} else {
  lines.push(`📝 Nội dung: ${source.message || 'Không có mô tả'}`);
}
return [{ json: {
  received_at: source.timestamp || new Date().toISOString(),
  event_type: eventType,
  event_label: eventLabel,
  kind: source.kind || '',
  message: source.message || '',
  app_version: source.app_version || '',
  method: source.method || '',
  method_label: methodLabel,
  code: source.code || '',
  error_title: eventType === 'automation_error' ? errorTitle : '',
  error_detail: eventType === 'automation_error' ? errorDetail : '',
  suggestion: eventType === 'automation_error' ? suggestion : '',
  module: source.module || '',
  filter_kind: source.filter_kind || '',
  run_id: source.run_id || '',
  elapsed_ms: source.elapsed_ms ?? '',
  user_id: account.user_id || '',
  company_id: account.company_id || '',
  division,
  os: diagnostics.os || source.os || '',
  os_release: diagnostics.os_release || source.os_release || '',
  python: diagnostics.python || source.python || '',
  chrome_alive: diagnostics.chrome_alive ?? '',
  session_active: diagnostics.session_active ?? '',
  recent_jobs: Array.isArray(diagnostics.recent_jobs) ? diagnostics.recent_jobs : [],
  notification_text: lines.filter(Boolean).join('\n')
} }];
